package volunteerops
import("testing";"time")
func TestEligibilityPolicies(t *testing.T){p:=EligibilityPolicy{MinimumAge:16,RequiredTraining:[]string{"safety"},MaximumWeeklyMinutes:120};if p.Check(Candidate{"v",15,[]string{"safety"},0})==nil{t.Fatal("expected age rejection")};if p.Check(Candidate{"v",17,[]string{},0})==nil{t.Fatal("expected training rejection")};if p.Check(Candidate{"v",17,[]string{"safety"},60})!=nil{t.Fatal("expected eligible")}}
func TestRankingAndReports(t *testing.T){start:=time.Date(2030,1,1,9,0,0,0,time.UTC);s:=Shift{ID:"s",Start:start,End:start.Add(time.Hour),Capacity:2,RequiredSkills:[]string{"desk"},Assigned:[]string{"a"}};vols:=map[string]Volunteer{"a":{ID:"a",Skills:[]string{"desk"},AvailableFrom:start,AvailableTo:start.Add(time.Hour)}};rank:=RankCandidates(s,[]Candidate{{"a",18,[]string{"safety"},30}},vols,EligibilityPolicy{MinimumAge:16,RequiredTraining:[]string{"safety"}});if len(rank)!=1{t.Fatal(rank)};if Summarize(s).FillRate!=.5{t.Fatal("fill rate")};if WeeklyMinutes([]Shift{s},"a")!=60{t.Fatal("weekly minutes")}}
